        path: "calc.mjs",
        blocks: "<<<<<<< SEARCH\nexport const add = (a, b) => a - b;\n=======\nexport const add = (a, b) => a + b;\n>>>>>>> REPLACE",
      },
      reason: "replace subtraction with addition",
    }));
  };
  const result = await runMission({
    id: "urn:test:mission:early-quorum",
    objective: "Repair the add function so the declared test passes.",
    territory,
    verifyCommand: "node --test calc.test.mjs",
    actors: 3,
    maxRounds: 10,
    minVerifiedCandidates: 1,
    apply: false,
  }, { dispatch, ledgerRoot });

  assert.equal(result.outcome.verified, true);
  assert.equal(result.metrics.rounds, 1);
  assert.equal(dispatchCalls, 1);
});"}]},"reason":"Add regression test proving runMission stops dispatching after minVerifiedCandidates is reached in wave 1"}]}]

